  /**
   * @method
   * @name createMarketBuyOrderWithCost
   * @description create a market buy order on a prediction outcome by providing
   * the cost
   * @param {string} outcome unified outcome handle
   * @param {float} cost how much you want to spend, in cost terms
   * @param {object} [params] extra exchange-specific parameters
   * @returns {object} a prediction [order
   * structure](https://docs.ccxt.com/#/?id=order-structure)
   */
  virtual std::shared_future<ccxt::any>
  createMarketBuyOrderWithCost(ccxt::any outcome, ccxt::any cost,
                               ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 // safeBool, not ::getValue(this,
                 // std::string("options"))['...'] — a raw missing-key access
                 // throws KeyError in Python/PHP when the option is undeclared
                 // (it is for every prediction exchange)
                 if (isTrue(
                         isTrue(this->safeBool(
                             this->options,
                             std::string("createMarketBuyOrderRequiresPrice"),
                             false)) ||
                         isTrue(this->safeBool(
                             this->has,
                             std::string("createMarketBuyOrderWithCost"),
                             false)))) {
                   return awaitValue(
                       this->createOrder(outcome, std::string("market"),
                                         std::string("buy"), cost, 1, params));
                 }
                 throw NotSupported(toString(
                     add(this->id, std::string(" createMarketBuyOrderWithCost()"
                                               " is not supported yet"))));
                 return ccxt::any{};
               })
        .share();
  }

